1	"use client";
2	
3	import { useEffect } from "react";
4	
5	/**
6	 * Invisible helper mounted on every dashboard page. If the visitor arrived via a
7	 * partner deep link (?ref=kodely — from /api/partner/checkout), it stashes the
8	 * partner id in a cookie so payAndDeploy / purchaseDomain can tag the resulting
9	 * order with `partnerSource`, WITHOUT threading a query param through every
10	 * intermediate wizard step and redirect. Mirrors ReferralCapture's pattern.
11	 *
12	 * 24h TTL: this is "attribute the order placed in this session", not a durable
13	 * referral — much shorter-lived than the 30-day referral cookie.
14	 */
15	const KNOWN_PARTNERS = ["kodely"];
16	
17	export function PartnerSourceCapture() {
18	  useEffect(() => {
19	    try {
20	      const params = new URLSearchParams(window.location.search);
21	      const ref = params.get("ref");
22	      if (!ref) return;
23	      const id = ref.trim().toLowerCase().slice(0, 32);
24	      if (!KNOWN_PARTNERS.includes(id)) return;
25	      document.cookie = `nx_partner_ref=${encodeURIComponent(id)}; path=/; max-age=${60 * 60 * 24}; SameSite=Lax`;
26	    } catch {
27	      /* non-fatal */
28	    }
29	  }, []);
30	  return null;
31	}
32

1	import { createHmac, timingSafeEqual } from "node:crypto";
2	import type { cookies } from "next/headers";
3	import { getSetting } from "@/lib/settings";
4	
5	/**
6	 * Partner API + SSO foundation. Lets a trusted first-party client (Kodely) act on
7	 * behalf of a linked Nxeon account: one identity, one wallet, Nxeon does the
8	 * provisioning/billing. Two trust mechanisms:
9	 *
10	 *  1. Server-to-server API key (`X-Api-Key`) — for Kodely's backend → Nxeon calls.
11	 *  2. Signed SSO codes — a short-lived, HMAC-signed authorization code minted by
12	 *     Nxeon's /sso/authorize (after the user logs in) and exchanged by Kodely's
13	 *     backend for the linked Nxeon identity. Stateless (no DB), like the existing
14	 *     marketing-unsub token, keyed by AUTH_SECRET.
15	 */
16	
17	function secret(): string {
18	  const s = process.env.AUTH_SECRET;
19	  if (!s) throw new Error("AUTH_SECRET is not set — cannot sign partner tokens");
20	  return s;
21	}
22	
23	// ---- Partner API key (server-to-server) -----------------------------------
24	
25	/** The shared secret Kodely's backend sends as `X-Api-Key`. Set in Settings. */
26	export async function partnerApiKey(): Promise<string> {
27	  return (await getSetting("kodely_partner_api_key", "")).trim();
28	}
29	
30	/** Constant-time check of an incoming `X-Api-Key` against the configured key. */
31	export async function verifyPartnerKey(presented: string | null | undefined): Promise<boolean> {
32	  const expected = await partnerApiKey();
33	  if (!expected || !presented) return false;
34	  const a = Buffer.from(presented);
35	  const b = Buffer.from(expected);
36	  if (a.length !== b.length) return false;
37	  return timingSafeEqual(a, b);
38	}
39	
40	/** Gate a partner route. Returns true if the request carries a valid key. */
41	export async function isPartnerRequest(req: Request): Promise<boolean> {
42	  return verifyPartnerKey(req.headers.get("x-api-key"));
43	}
44	
45	// ---- SSO authorization codes (browser handshake) --------------------------
46	
47	const SSO_TTL_MS = 5 * 60_000; // codes are single-use-window, 5 minutes
48	
49	type SsoPayload = { u: string; c: string; r: string; e: number };
50	
51	function b64urlJson(obj: unknown): string {
52	  return Buffer.from(JSON.stringify(obj)).toString("base64url");
53	}
54	
55	function ssoSig(payloadB64: string): string {
56	  return createHmac("sha256", secret()).update(`sso:${payloadB64}`).digest("base64url");
57	}
58	
59	/** Mint a signed code binding an Nxeon userId to a client + redirect_uri, 5-min TTL. */
60	export function mintSsoCode(userId: string, clientId: string, redirectUri: string): string {
61	  const payloadB64 = b64urlJson({ u: userId, c: clientId, r: redirectUri, e: Date.now() + SSO_TTL_MS } satisfies SsoPayload);
62	  return `${payloadB64}.${ssoSig(payloadB64)}`;
63	}
64	
65	/** Verify a code for a given client + redirect_uri. Returns the Nxeon userId or null. */
66	export function verifySsoCode(code: string | null | undefined, clientId: string, redirectUri: string): string | null {
67	  if (!code || !code.includes(".")) return null;
68	  const [payloadB64, sig] = code.split(".", 2);
69	  let expected: string;
70	  try {
71	    expected = ssoSig(payloadB64);
72	  } catch {
73	    return null;
74	  }
75	  const a = Buffer.from(sig);
76	  const b = Buffer.from(expected);
77	  if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
78	  let p: SsoPayload;
79	  try {
80	    p = JSON.parse(Buffer.from(payloadB64, "base64url").toString());
81	  } catch {
82	    return null;
83	  }
84	  if (p.c !== clientId || p.r !== redirectUri) return null;
85	  if (typeof p.e !== "number" || Date.now() > p.e) return null;
86	  return p.u || null;
87	}
88	
89	// ---- Redirect-URI allowlist (prevents open redirect) ----------------------
90	
91	/**
92	 * Allowed redirect_uri prefixes for the Kodely SSO client, comma-separated in the
93	 * `kodely_sso_redirects` Setting (e.g. "https://kodely.site,https://app.kodely.site").
94	 * A redirect_uri must start with one of these, over HTTPS.
95	 */
96	export async function isAllowedRedirect(redirectUri: string): Promise<boolean> {
97	  if (!/^https:\/\//i.test(redirectUri)) return false;
98	  const raw = (await getSetting("kodely_sso_redirects", "")).trim();
99	  if (!raw) return false;
100	  const allowed = raw.split(",").map((s) => s.trim().replace(/\/$/, "")).filter(Boolean);
101	  return allowed.some((a) => redirectUri === a || redirectUri.startsWith(a + "/") || redirectUri.startsWith(a + "?"));
102	}
103	
104	// ---- Outbound webhook to the partner (status callbacks) --------------------
105	
106	/**
107	 * Notify the partner (Kodely) of an async event (provision done, SSL live, …).
108	 * Best-effort, HMAC-signed with a DEDICATED webhook secret (`kodely_webhook_secret`)
109	 * — deliberately NOT AUTH_SECRET, which also signs every Nxeon session JWT and must
110	 * never leave this server; Kodely needs the signing key to verify the webhook, so it
111	 * has to be an independent, revocable secret of its own. No-op until both
112	 * `kodely_webhook_url` and `kodely_webhook_secret` are set.
113	 */
114	export async function notifyPartner(event: string, payload: Record<string, unknown>): Promise<void> {
115	  try {
116	    const url = (await getSetting("kodely_webhook_url", "")).trim();
117	    const whSecret = (await getSetting("kodely_webhook_secret", "")).trim();
118	    if (!url || !whSecret) return;
119	    const body = JSON.stringify({ event, payload, at: Date.now() });
120	    const sig = createHmac("sha256", whSecret).update(body).digest("base64url");
121	    await fetch(url, {
122	      method: "POST",
123	      headers: { "content-type": "application/json", "x-nxeon-signature": sig },
124	      body,
125	    });
126	  } catch {
127	    /* best-effort — a failed webhook must never break provisioning */
128	  }
129	}
130	
131	// ---- Order attribution (which orders came from a partner deep link) -------
132	
133	/** Known partner ids allowed to tag an order via ?ref= — anything else is dropped. */
134	export const PARTNER_IDS = ["kodely"] as const;
135	export type PartnerId = (typeof PARTNER_IDS)[number];
136	
137	export const PARTNER_SOURCE_COOKIE = "nx_partner_ref";
138	
139	/**
140	 * Read the partner-source cookie set by PartnerSourceCapture (a ?ref=kodely deep
141	 * link into /dashboard/deploy or /dashboard/domains). Used at ORDER-CREATION time
142	 * (payAndDeploy, purchaseDomain) to tag the Server/Domain row with `partnerSource`,
143	 * so the provision-success webhook (worker/index.ts, purchaseDomain) knows which
144	 * orders to notify the partner about — most orders are direct Nxeon customers and
145	 * must NEVER be forwarded to Kodely's webhook.
146	 */
147	export function partnerSourceFromCookie(jar: Awaited<ReturnType<typeof cookies>>): PartnerId | undefined {
148	  const v = jar.get(PARTNER_SOURCE_COOKIE)?.value;
149	  return (PARTNER_IDS as readonly string[]).includes(v ?? "") ? (v as PartnerId) : undefined;
150	}
