1	// CREATOR PARTNER PROGRAM — a creator code TYPED by the customer (2026-09-28).
2	//
3	// Until now a partner code only worked through the link /partner/<CODE>
4	// (app/partner/[code]/route.ts -> `nxeon_ref` cookie -> register() attaches the
5	// customer). A viewer told "use my code SAM" who simply TYPED it anywhere got
6	// nothing. This module is the one set of rules for the two places a code can now
7	// be typed:
8	//
9	//   1. /register's optional "Creator code" field -> lib/actions.ts register(),
10	//      which attaches through the SAME attachCustomerToPartnerByCode the cookie
11	//      path uses (a new account can't have a partner or a purchase yet, so only
12	//      "is this a real, ACTIVE partner code" needs checking — `signupCreatorCode`).
13	//
14	//   2. The deploy wizard's EXISTING promo-code box (components/nx/DeployView.tsx)
15	//      -> lib/actions-creator-code.ts. On an existing account the code attaches
16	//      the partner only when ALL of these hold (`creatorCodeVerdict`):
17	//        - it is a real partner code and NOT also a Coupon code (a Coupon with the
18	//          same code keeps the box's existing coupon meaning — nothing changes for
19	//          any coupon that works today);
20	//        - it is not the account's OWN partner code (no self-referral — the same
21	//          rule attachCustomerToPartnerByCode already enforces);
22	//        - the account is not already linked to a partner (attachment is permanent
23	//          and single — PartnerCustomer.customerId is UNIQUE);
24	//        - the partner is ACTIVE (a PAUSED partner gets no new customers, the same
25	//          gate the cookie path applies);
26	//        - the account has made NO paid purchase yet (`hasMadePaidPurchase`) —
27	//          "creator codes apply to a first purchase". Without this, an existing
28	//          customer could type any creator's code and pick up 50% off their NEXT
29	//          order plus a lifetime 10%, and the creator would earn commission on a
30	//          customer they never brought.
31	//
32	// Once attached, NOTHING new prices anything: the existing partner-discount path
33	// (lib/partner-pricing.ts partnerDiscountForNewOrder, read by orderQuote /
34	// gameOrderQuote and by the charge itself) sees the PartnerCustomer row and the
35	// quote and the charge pick up the discount together — displayed === charged is
36	// preserved by construction, not by a second formula.
37	
38	import type { Prisma } from "@prisma/client";
39	import { db } from "./db";
40	import { NON_COMMISSIONABLE_DESCRIPTIONS } from "./partner-commission";
41	
42	/** Same canonical form every partner-code reader already uses: trimmed, UPPERCASE. */
43	export function normalizeCreatorCode(raw: string | null | undefined): string {
44	  return String(raw ?? "").trim().toUpperCase().slice(0, 32);
45	}
46	
47	/** The character set app/partner/[code]/route.ts accepts for a code. */
48	export function looksLikeCreatorCode(code: string): boolean {
49	  return code.length >= 2 && /^[A-Z0-9_-]+$/.test(code);
50	}
51	
52	export type CreatorCodeRefusal = "inactive" | "own" | "linked" | "purchased";
53	
54	export type CreatorCodeVerdict =
55	  /** Not a creator code (unknown, or a Coupon owns this code) — the promo box
56	   *  falls back to its normal coupon handling. */
57	  | { kind: "none" }
58	  | { kind: "eligible"; code: string; partnerName: string }
59	  /** Already linked to THIS creator — nothing to do, the discount already applies. */
60	  | { kind: "linked-same"; code: string; partnerName: string }
61	  | { kind: "refused"; code: string; reason: CreatorCodeRefusal; message: string };
62	
63	export const CREATOR_CODE_MESSAGES: Record<CreatorCodeRefusal, string> = {
64	  own: "That's your own creator code — it can't be used on your own account.",
65	  linked: "This account is already linked to a creator.",
66	  inactive: "This creator code isn't active right now.",
67	  purchased: "Creator codes apply to a first purchase — this account has already bought something.",
68	};
69	
70	/**
71	 * Pure decision (unit-tested in test/creator-code.test.ts). The order of the
72	 * checks decides which message a customer sees when more than one applies; the
73	 * most specific, most actionable one wins.
74	 */
75	export function creatorCodeVerdict(facts: {
76	  code: string;
77	  couponExists: boolean;
78	  partner: { id: string; name: string; status: string; userId: string | null } | null;
79	  customerId: string;
80	  attachedPartnerId: string | null;
81	  hasPaidPurchase: boolean;
82	}): CreatorCodeVerdict {
83	  const { code, partner } = facts;
84	  if (!partner || facts.couponExists) return { kind: "none" };
85	  const refuse = (reason: CreatorCodeRefusal): CreatorCodeVerdict =>
86	    ({ kind: "refused", code, reason, message: CREATOR_CODE_MESSAGES[reason] });
87	  if (partner.userId && partner.userId === facts.customerId) return refuse("own");
88	  if (facts.attachedPartnerId) {
89	    return facts.attachedPartnerId === partner.id
90	      ? { kind: "linked-same", code, partnerName: partner.name }
91	      : refuse("linked");
92	  }
93	  if (partner.status !== "ACTIVE") return refuse("inactive");
94	  if (facts.hasPaidPurchase) return refuse("purchased");
95	  return { kind: "eligible", code, partnerName: partner.name };
96	}
97	
98	/**
99	 * Has this account bought anything? A PAID (or since REFUNDED — a refund must not
100	 * reopen the first-purchase window) invoice with a positive total that is not a
101	 * wallet top-up, the same "is this a real sale" classifier commission accrual uses
102	 * (lib/partner-commission.ts isCommissionableInvoice) — or any non-free server row.
103	 * Covers every product (VPS, game, hosting, email, domains, add-ons) because every
104	 * one of them issues an Invoice.
105	 */
106	export async function hasMadePaidPurchase(
107	  userId: string,
108	  client: Prisma.TransactionClient | typeof db = db,
109	): Promise<boolean> {
110	  const [invoices, servers] = await Promise.all([
111	    client.invoice.count({
112	      where: {
113	        userId,
114	        status: { in: ["PAID", "REFUNDED"] },
115	        amountCents: { gt: 0 },
116	        description: { notIn: [...NON_COMMISSIONABLE_DESCRIPTIONS] },
117	      },
118	    }),
119	    client.server.count({ where: { userId, isFree: false } }),
120	  ]);
121	  return invoices > 0 || servers > 0;
122	}
123	
124	async function gatherFacts(client: Prisma.TransactionClient | typeof db, userId: string, code: string) {
125	  const [coupon, partner, attachment, hasPaidPurchase] = await Promise.all([
126	    client.coupon.findUnique({ where: { code }, select: { id: true } }),
127	    client.referralPartner.findUnique({
128	      where: { code },
129	      select: { id: true, name: true, status: true, userId: true },
130	    }),
131	    client.partnerCustomer.findUnique({ where: { customerId: userId }, select: { partnerId: true } }),
132	    hasMadePaidPurchase(userId, client),
133	  ]);
134	  return {
135	    code,
136	    couponExists: !!coupon,
137	    partner,
138	    customerId: userId,
139	    attachedPartnerId: attachment?.partnerId ?? null,
140	    hasPaidPurchase,
141	  };
142	}
143	
144	/** Read-only: what would typing this code into the promo box do for this account? */
145	export async function resolveCreatorCode(userId: string, rawCode: string): Promise<CreatorCodeVerdict> {
146	  const code = normalizeCreatorCode(rawCode);
147	  if (!looksLikeCreatorCode(code)) return { kind: "none" };
148	  return creatorCodeVerdict(await gatherFacts(db, userId, code));
149	}
150	
151	/**
152	 * Attach the account to the creator whose code this is, re-running every rule
153	 * inside one transaction. Returns the verdict that applied: `eligible` means the
154	 * attachment was made by THIS call. A concurrent attach (the UNIQUE customerId)
155	 * resolves to `linked-same`/`refused: linked` on a re-read, never a crash.
156	 */
157	export async function attachCreatorCode(userId: string, rawCode: string): Promise<CreatorCodeVerdict> {
158	  const code = normalizeCreatorCode(rawCode);
159	  if (!looksLikeCreatorCode(code)) return { kind: "none" };
160	  try {
161	    return await db.$transaction(async (tx) => {
162	      const verdict = creatorCodeVerdict(await gatherFacts(tx, userId, code));
163	      if (verdict.kind !== "eligible") return verdict;
164	      const partner = await tx.referralPartner.findUniqueOrThrow({ where: { code }, select: { id: true } });
165	      await tx.partnerCustomer.create({ data: { partnerId: partner.id, customerId: userId } });
166	      return verdict;
167	    });
168	  } catch (e) {
169	    if ((e as Prisma.PrismaClientKnownRequestError)?.code === "P2002") {
170	      return resolveCreatorCode(userId, code);
171	    }
172	    throw e;
173	  }
174	}
175	
176	/**
177	 * Register-page check: a brand-new account has no partner and no purchase, so the
178	 * only question is whether the typed code is a real, ACTIVE partner code. The
179	 * attachment itself then goes through attachCustomerToPartnerByCode, exactly like
180	 * the cookie path.
181	 */
182	export async function signupCreatorCode(
183	  rawCode: string,
184	): Promise<{ ok: true; code: string; partnerName: string } | { ok: false; error: string }> {
185	  const code = normalizeCreatorCode(rawCode);
186	  const invalid = "That creator code isn't valid. Check the spelling, or clear the field to sign up without one.";
187	  if (!looksLikeCreatorCode(code)) return { ok: false, error: invalid };
188	  const partner = await db.referralPartner.findUnique({ where: { code }, select: { name: true, status: true } });
189	  if (!partner) return { ok: false, error: invalid };
190	  if (partner.status !== "ACTIVE") return { ok: false, error: CREATOR_CODE_MESSAGES.inactive };
191	  return { ok: true, code, partnerName: partner.name };
192	}
