1	import { redirect } from "next/navigation";
2	import { cookies } from "next/headers";
3	import { RegisterForm } from "@/components/AuthForms";
4	import { AuthShell } from "@/components/marketing/AuthShell";
5	import { ReferralCapture } from "@/components/customer/ReferralCapture";
6	import { currentUser } from "@/lib/auth";
7	import { safeNext } from "@/lib/safe-next";
8	import { googleOauthConfigured } from "@/lib/google-oauth";
9	import { discordOauthConfigured } from "@/lib/discord-oauth";
10	import { partnerPreviewForCode } from "@/lib/partner-pricing";
11	import { normalizeCreatorCode, looksLikeCreatorCode } from "@/lib/creator-code";
12	
13	/** Friendly copy for the `?error=` codes the Google OAuth routes bounce back. */
14	const GOOGLE_ERRORS: Record<string, string> = {
15	  google_unavailable: "Google sign-in isn't set up on this server yet. Use your email and password.",
16	  google_ratelimited: "Too many sign-in attempts. Please wait a moment and try again.",
17	  google_cancelled: "Google sign-in was cancelled.",
18	  google_state: "That Google sign-in link expired or didn't match. Please try again.",
19	  google_unverified: "Your Google email isn't verified, so we can't sign you in with it.",
20	  google_error: "Couldn't finish signing in with Google. Please try again.",
21	  account_suspended: "This account is suspended.",
22	};
23	
24	/** Same convention as GOOGLE_ERRORS — see app/login/page.tsx's DISCORD_ERRORS. */
25	const DISCORD_ERRORS: Record<string, string> = {
26	  discord_unavailable: "Discord sign-in isn't set up on this server yet. Use your email and password.",
27	  discord_ratelimited: "Too many sign-in attempts. Please wait a moment and try again.",
28	  discord_cancelled: "Discord connection cancelled.",
29	  discord_state: "That Discord sign-in link expired or didn't match. Please try again.",
30	  discord_unverified_email: "Your Discord account needs a verified email to sign up this way. Verify it on Discord, or create a Nxeon account normally and connect Discord from Settings afterward.",
31	  discord_email_taken: "An account with this email already exists. Log in normally, then connect Discord from Settings.",
32	  discord_suspended: "This account is suspended.",
33	  discord_error: "Couldn't finish signing in with Discord. Please try again.",
34	};
35	
36	export default async function RegisterPage({
37	  searchParams,
38	}: {
39	  searchParams: Promise<{ next?: string; error?: string; ref?: string }>;
40	}) {
41	  // Where the visitor was heading before hitting the sign-up wall. Carried
42	  // through the Google OAuth flow so first sign-in lands them where they meant to
43	  // go. Validated by `safeNext` — an unchecked `next` is an open redirect and
44	  // therefore a phishing primitive — so it is never trusted, here or in the action.
45	  const { next, error, ref } = await searchParams;
46	  const dest = safeNext(next ?? null);
47	  // Only ever surface a message from our own fixed map — never echo the raw
48	  // query value into the page.
49	  const googleError = error ? GOOGLE_ERRORS[error] : undefined;
50	  const discordError = error ? DISCORD_ERRORS[error] : undefined;
51	  const discordEnabled = await discordOauthConfigured();
52	
53	  // Already signed in? Then this page is a waypoint: send them onward instead of
54	  // asking a paying customer to authenticate again.
55	  const user = await currentUser();
56	  if (user) redirect(dest ?? (user.role === "ADMIN" ? "/admin" : "/dashboard"));
57	
58	  // Creator code pre-fill: a visitor who came through /partner/<code> carries the
59	  // `nxeon_ref` cookie; one on /register?ref=<code> has it in the URL (ReferralCapture
60	  // only writes the cookie after hydration, so read the param here too). Pre-filled
61	  // ONLY when it is a real, ACTIVE creator code — a peer "refer a friend" code in the
62	  // same cookie is not a creator code and keeps its own (unchanged) cookie path.
63	  const jar = await cookies();
64	  const carried = normalizeCreatorCode(ref ?? jar.get("nxeon_ref")?.value ?? "");
65	  let creatorCode: string | undefined;
66	  let creatorName: string | null = null;
67	  if (looksLikeCreatorCode(carried)) {
68	    const preview = await partnerPreviewForCode(carried);
69	    if (preview.active) {
70	      creatorCode = carried;
71	      creatorName = preview.partnerName;
72	    }
73	  }
74	
75	  return (
76	    <AuthShell
77	      heading="Create your account"
78	      sub="Deploy your first server in under a minute."
79	      // Two of these three were untrue. "No credit card required to get started"
80	      // implied a free first server — free deploys are admin-only, and a customer
81	      // with a $0 wallet gets "Insufficient balance. Top up your wallet first."
82	      // And "18+ OS images" was a hardcode the live catalogue passed long ago:
83	      // the homepage counts the same catalogue and renders 31+. A number nothing
84	      // computes goes stale by default, so this states the capability instead.
85	      bullets={[
86	        "Free to create — you pay when you deploy",
87	        "One-click OS images, control panels and apps",
88	        "Pay monthly, cancel anytime",
89	      ]}
90	    >
91	      <ReferralCapture />
92	      <RegisterForm
93	        next={dest ?? undefined}
94	        googleEnabled={googleOauthConfigured()}
95	        googleError={googleError}
96	        discordEnabled={discordEnabled}
97	        discordError={discordError}
98	        creatorCode={creatorCode}
99	        creatorName={creatorName}
100	      />
101	    </AuthShell>
102	  );
103	}
104

1	import { test } from "node:test";
2	import assert from "node:assert/strict";
3	import { creatorCodeVerdict, normalizeCreatorCode, looksLikeCreatorCode, CREATOR_CODE_MESSAGES } from "../lib/creator-code.ts";
4	import { maskEmail } from "../lib/mask-email.ts";
5	import {
6	  MIN_PAYOUT_THRESHOLD_CENTS,
7	  partnerPayoutThresholdLabel,
8	  partnerPayoutPolicyText,
9	} from "../lib/partner-payout.ts";
10	
11	/**
12	 * Creator codes typed into /register or the deploy wizard's promo box
13	 * (lib/creator-code.ts), partner-facing email masking (lib/mask-email.ts) and the
14	 * stated payout policy (lib/partner-payout.ts). Pure functions, no DB.
15	 */
