36	  for (let i = 0; i < 6; i++) {
37	    const code = generateReferralCode();
38	    const clash = await db.user.findUnique({ where: { referralCode: code } });
39	    if (!clash) return code;
40	  }
41	  return generateReferralCode(12);
42	}
