44	/**
45	 * Step 2 of "Login with Google": the OAuth redirect target.
46	 *
47	 * Verifies CSRF `state` against the httpOnly cookie, exchanges the code for a
48	 * token, reads the OIDC profile, then finds/links/creates the local account and
49	 * issues the SAME session cookie a normal password login does (`createSession`).
50	 * No token is ever logged or placed in a URL. Any failure redirects to /login
51	 * with a friendly `error` code.
52	 *
53	 * NOTE: this is a Route Handler, NOT a `"use server"` action, so it adds no new
54	 * server-action endpoint and the customer-action guard test is unaffected.
55	 */
56	export async function GET(req: NextRequest) {
57	  if (!googleOauthConfigured()) return fail("google_unavailable");
58	
59	  const raw = req.cookies.get(STATE_COOKIE)?.value;
60	  let stash: Stash = {};
61	  try {
62	    stash = raw ? (JSON.parse(raw) as Stash) : {};
63	  } catch {
64	    stash = {};
65	  }
66	  const next = safeNext(stash.next ?? null);
67	
68	  const sp = req.nextUrl.searchParams;
69	
70	  // The user declined on Google's consent screen, or Google itself errored
71	  // (e.g. the app is still in "testing" mode and this user isn't a test user).
72	  const oauthError = sp.get("error");
73	  if (oauthError) {
74	    return fail(oauthError === "access_denied" ? "google_cancelled" : "google_error");
75	  }
76	
77	  // CSRF: the returned state must match the cookie minted by the start route.
78	  const state = sp.get("state") ?? "";
79	  if (!stash.state || !state || state !== stash.state) {
80	    return fail("google_state");
81	  }
82	
83	  const code = sp.get("code") ?? "";
84	  if (!code) return fail("google_error");
85	
86	  const exchanged = await googleExchangeCode(code);
87	  if (!exchanged.accessToken) return fail("google_error");
88	
89	  const { profile } = await googleFetchProfile(exchanged.accessToken);
90	  if (!profile) return fail("google_error");
91	
92	  // Google must have verified control of the address, else linking/creating an
93	  // account on it would trust an address the user never proved they own.
94	  if (!profile.emailVerified) return fail("google_unverified");
95	
96	  const email = normalizeEmail(profile.email);
97	  if (!email) return fail("google_error");
98	
99	  // 1) Existing Google link → sign in.
100	  let user = await db.user.findUnique({ where: { googleId: profile.sub } });
101	
102	  // 2) Existing account by email → link Google onto it (lets a password user
103	  //    sign in with Google). Google already verified the address, so also stamp
104	  //    email verification if it was never proven locally.
105	  if (!user) {
106	    const byEmail = await db.user.findUnique({ where: { email } });
107	    if (byEmail) {
108	      user = await db.user.update({
109	        where: { id: byEmail.id },
110	        data: {
111	          googleId: profile.sub,
112	          avatarUrl: byEmail.avatarUrl ?? profile.picture,
113	          emailVerifiedAt: byEmail.emailVerifiedAt ?? new Date(),
114	        },
115	      });
116	      await db.auditLog
117	        .create({ data: { userId: user.id, action: "user.google_link", detail: "Linked Google to existing account" } })
118	        .catch(() => {});
119	    }
120	  }
121	
122	  // 3) No account yet → create one. `passwordHash` is required and this account
123	  //    has no password, so store a random, unusable bcrypt hash: it can never
124	  //    match any input, so the account can't be password-logged-in until the
125	  //    user sets a password (via forgot-password). Google verified the email, so
126	  //    it starts verified.
127	  if (!user) {
128	    const unusableHash = await bcrypt.hash(randomUrlSafe(24), 12);
129	    try {
130	      user = await db.user.create({
131	        data: {
132	          email,
133	          name: profile.name || email.split("@")[0] || "Nxeon user",
134	          passwordHash: unusableHash,
135	          googleId: profile.sub,
136	          avatarUrl: profile.picture,
137	          emailVerifiedAt: new Date(),
138	          referralCode: await uniqueReferralCode(),
139	        },
140	      });
141	    } catch {
142	      // Almost certainly a race on the unique email/googleId index — re-resolve.
143	      user =
144	        (await db.user.findUnique({ where: { googleId: profile.sub } })) ??
145	        (await db.user.findUnique({ where: { email } }));
146	      if (!user) return fail("google_error");
147	    }
148	    await db.auditLog
149	      .create({ data: { userId: user.id, action: "user.google_register", detail: "Signed up with Google" } })
150	      .catch(() => {});
151	    // Parity with password signup: idempotent welcome credit + welcome email.
152	    // Google verified the email already, so no verification link is sent. The
153	    // credit claim only pays a row whose signupCreditCents is still 0, so a rare
154	    // concurrent-signup race can never pay twice.
155	    try {
156	      const cents = await getSettingInt("signup_free_credit_cents", signupFreeCreditCents());
157	      if (cents > 0) {
158	        const claimed = await db.user.updateMany({
159	          where: { id: user.id, signupCreditCents: 0 },
160	          data: { balanceCents: { increment: cents }, signupCreditCents: cents },
161	        });
162	        if (claimed.count > 0) {
163	          await db.walletTransaction.create({ data: { userId: user.id, amountCents: cents, description: "Welcome credit" } });
164	        }
165	      }
166	    } catch (e) {
167	      console.error("[google] signup credit grant failed for", user.id, e);
168	    }
169	    try {
170	      const { sendMail, emails } = await import("@/lib/mailer");
171	      const tpl = emails.welcome(user.name || "");
172	      await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html, userId: user.id, kind: "welcome" });
173	    } catch {
174	      /* welcome email is best-effort, exactly like password signup */
175	    }
176	  }
177	
178	  if (user.suspended) return fail("account_suspended");
179	
180	  await db.auditLog.create({ data: { userId: user.id, action: "user.login", detail: "Google" } }).catch(() => {});
181	
182	  // Issue the exact same session a password login issues.
183	  await createSession(user.id);
184	
185	  return finish(
186	    NextResponse.redirect(`${base()}${next ?? (user.role === "ADMIN" ? "/admin" : "/dashboard")}`),
187	  );
188	}
