36	async function grantSignupCredit(userId: string): Promise<void> {
37	  const cents = await getSettingInt("signup_free_credit_cents", signupFreeCreditCents());
38	  if (cents <= 0) return;
39	  const claimed = await db.user.updateMany({
40	    where: { id: userId, signupCreditCents: 0 },
41	    data: { balanceCents: { increment: cents }, signupCreditCents: cents },
42	  });
43	  if (claimed.count === 0) return;
44	  await db.walletTransaction.create({ data: { userId, amountCents: cents, description: "Welcome credit" } });
