47	/** `error` is a short CODE (mirrors the Google flow's GOOGLE_ERRORS convention
48	 *  in app/login/page.tsx) — never a raw sentence, so nothing server-derived
49	 *  ever gets echoed unescaped into a `?error=` query value. */
50	export type DiscordAuthResult =
51	  | { ok: true; userId: string; isNewAccount: boolean }
52	  | { ok: false; error: "discord_suspended" | "discord_unverified_email" | "discord_email_taken" | "discord_error" };
53	
54	/**
55	 * Log in (if this Discord account is already linked), or create a new Nxeon
56	 * account (if Discord returned a verified email that matches no existing
57	 * account), for the unauthenticated "Continue with Discord" flow.
58	 *
59	 * SECURITY: the one real risk in this whole feature is silently signing
60	 * someone into (or merging into) an account that isn't theirs. Two hard
61	 * rules enforce that:
62	 *   1. An EXISTING Nxeon account is only ever signed into via its own
63	 *      `discordUserId` — never derived from a matching email at login time.
64	 *   2. A NEW account is only ever created when Discord reports the email as
65	 *      `verified: true` on ITS side — an unverified email is refused
66	 *      outright rather than trusted for either matching or creation. If a
67	 *      verified email collides with an existing password-based account
68	 *      that has no Discord link yet, this returns an error asking them to
69	 *      log in normally and connect Discord from Settings — never an
70	 *      auto-login or silent merge.
71	 */
72	export async function loginOrSignupWithDiscord(discordUser: DiscordSelfUser, userAccessToken: string): Promise<DiscordAuthResult> {
73	  // 1. Already linked — this IS them, full stop.
74	  const linked = await db.user.findUnique({ where: { discordUserId: discordUser.id } as any, select: { id: true, suspended: true } });
75	  if (linked) {
76	    if (linked.suspended) return { ok: false, error: "discord_suspended" };
77	    await createSession(linked.id);
78	    await recordAudit(linked.id, "user.login", "discord");
79	    await joinAndSyncBestEffort(linked.id, discordUser.id, userAccessToken);
80	    return { ok: true, userId: linked.id, isNewAccount: false };
81	  }
82	
83	  // 2. Not linked — need a verified email to go any further.
84	  if (!discordUser.email || !discordUser.emailVerified) {
85	    return { ok: false, error: "discord_unverified_email" };
86	  }
87	  const email = normalizeEmail(discordUser.email);
88	
89	  // 3. Email matches an existing (password-based, unlinked) account —
90	  // refuse to auto-login or auto-merge. See top-of-file SECURITY note.
91	  const existingByEmail = await db.user.findUnique({ where: { email }, select: { id: true } });
92	  if (existingByEmail) {
93	    return { ok: false, error: "discord_email_taken" };
94	  }
95	
96	  // 4. Genuinely new — create the account. Password-less: a long random
97	  // hash nobody knows, same as this account would end up with no
98	  // meaningfully-guessable credential either way. "Forgot password" still
99	  // works later if they ever want a real password too.
100	  const referralCode = await uniqueReferralCode();
101	  const randomPassword = randomBytes(32).toString("hex");
102	  const user = await db.user.create({
103	    data: {
104	      email,
105	      name: discordUser.username || "Nxeon user",
106	      passwordHash: await bcrypt.hash(randomPassword, 12),
107	      referralCode,
108	      discordUserId: discordUser.id,
109	      emailVerifiedAt: new Date(), // Discord already verified it on their side.
110	    } as any,
111	  });
112	  await recordAudit(user.id, "user.register", "discord");
113	  try {
114	    await grantSignupCredit(user.id);
115	  } catch (e) {
116	    console.error("[discord-auth] signup credit grant failed for", user.id, e);
117	  }
118	  await createSession(user.id);
119	  await joinAndSyncBestEffort(user.id, discordUser.id, userAccessToken);
120	  return { ok: true, userId: user.id, isNewAccount: true };
121	}
