123	/** Add them to the Nxeon Discord server (guilds.join) and sync their badge roles — best-effort, never blocks login/signup. */
124	async function joinAndSyncBestEffort(userId: string, discordUserId: string, userAccessToken: string): Promise<void> {
125	  if (!(await discordEnabled())) return;
126	  try {
127	    const guildId = await discordGuildId();
128	    if (!guildId) return;
129	    const verifiedRoleId = await getSetting("discord_role_verified_id", "");
130	    await joinGuildWithAccessToken(discordUserId, userAccessToken, verifiedRoleId ? [verifiedRoleId] : undefined);
131	    await syncDiscordRoles(userId);
132	  } catch (e) {
133	    console.error("[discord-auth] joinAndSyncBestEffort failed (non-fatal)", userId, e);
134	  }
135	}
