42	  // through the Google OAuth flow so first sign-in lands them where they meant to
43	  // go. Validated by `safeNext` — an unchecked `next` is an open redirect and
44	  // therefore a phishing primitive — so it is never trusted, here or in the action.
45	  const { next, error, ref } = await searchParams;
46	  const dest = safeNext(next ?? null);
47	  // Only ever surface a message from our own fixed map — never echo the raw
48	  // query value into the page.
49	  const googleError = error ? GOOGLE_ERRORS[error] : undefined;
50	  const discordError = error ? DISCORD_ERRORS[error] : undefined;
51	  const discordEnabled = await discordOauthConfigured();
52	
53	  // Already signed in? Then this page is a waypoint: send them onward instead of
54	  // asking a paying customer to authenticate again.
55	  const user = await currentUser();
