66	  let creatorName: string | null = null;
67	  if (looksLikeCreatorCode(carried)) {
68	    const preview = await partnerPreviewForCode(carried);
69	    if (preview.active) {
70	      creatorCode = carried;
71	      creatorName = preview.partnerName;
72	    }
73	  }
74	
75	  return (
76	    <AuthShell
77	      heading="Create your account"
78	      sub="Deploy your first server in under a minute."
79	      // Two of these three were untrue. "No credit card required to get started"
80	      // implied a free first server — free deploys are admin-only, and a customer
81	      // with a $0 wallet gets "Insufficient balance. Top up your wallet first."
82	      // And "18+ OS images" was a hardcode the live catalogue passed long ago:
83	      // the homepage counts the same catalogue and renders 31+. A number nothing
