55	 * with a friendly `error` code.
56	 *
57	 * NOTE: this is a Route Handler, NOT a `"use server"` action, so it adds no new
58	 * server-action endpoint and the customer-action guard test is unaffected.
59	 */
60	export async function GET(req: NextRequest) {
61	  if (!googleOauthConfigured()) return fail("google_unavailable");
62	
63	  const raw = req.cookies.get(STATE_COOKIE)?.value;
64	  let stash: Stash = {};
65	  try {
66	    stash = raw ? (JSON.parse(raw) as Stash) : {};
67	  } catch {
68	    stash = {};
69	  }
70	  const next = safeNext(stash.next ?? null);
71	
72	  const sp = req.nextUrl.searchParams;
73	
74	  // The user declined on Google's consent screen, or Google itself errored
75	  // (e.g. the app is still in "testing" mode and this user isn't a test user).
76	  const oauthError = sp.get("error");
77	  if (oauthError) {
78	    return fail(oauthError === "access_denied" ? "google_cancelled" : "google_error");
79	  }
80	
81	  // CSRF: the returned state must match the cookie minted by the start route.
82	  const state = sp.get("state") ?? "";
83	  if (!stash.state || !state || state !== stash.state) {
84	    return fail("google_state");
85	  }
86	
87	  const code = sp.get("code") ?? "";
88	  if (!code) return fail("google_error");
89	
90	  const exchanged = await googleExchangeCode(code);
91	  if (!exchanged.accessToken) return fail("google_error");
92	
93	  const { profile } = await googleFetchProfile(exchanged.accessToken);
94	  if (!profile) return fail("google_error");
95	
96	  // Google must have verified control of the address, else linking/creating an
97	  // account on it would trust an address the user never proved they own.
98	  if (!profile.emailVerified) return fail("google_unverified");
99	
100	  const email = normalizeEmail(profile.email);
101	  if (!email) return fail("google_error");
102	
103	  // 1) Existing Google link → sign in.
104	  let user = await db.user.findUnique({ where: { googleId: profile.sub } });
105	
106	  // 2) Existing account by email → link Google onto it (lets a password user
107	  //    sign in with Google). Google already verified the address, so also stamp
108	  //    email verification if it was never proven locally.
109	  if (!user) {
110	    const byEmail = await db.user.findUnique({ where: { email } });
111	    if (byEmail) {
112	      user = await db.user.update({
113	        where: { id: byEmail.id },
114	        data: {
115	          googleId: profile.sub,
116	          avatarUrl: byEmail.avatarUrl ?? profile.picture,
117	          emailVerifiedAt: byEmail.emailVerifiedAt ?? new Date(),
118	        },
119	      });
120	      await db.auditLog
121	        .create({ data: { userId: user.id, action: "user.google_link", detail: "Linked Google to existing account" } })
122	        .catch(() => {});
123	    }
124	  }
125	
126	  // 3) No account yet → create one. `passwordHash` is required and this account
127	  //    has no password, so store a random, unusable bcrypt hash: it can never
128	  //    match any input, so the account can't be password-logged-in until the
129	  //    user sets a password (via forgot-password). Google verified the email, so
130	  //    it starts verified.
131	  if (!user) {
132	    const unusableHash = await bcrypt.hash(randomUrlSafe(24), 12);
133	    try {
134	      user = await db.user.create({
135	        data: {
136	          email,
137	          name: profile.name || email.split("@")[0] || "Nxeon user",
138	          passwordHash: unusableHash,
139	          googleId: profile.sub,
140	          avatarUrl: profile.picture,
141	          emailVerifiedAt: new Date(),
142	          referralCode: await uniqueReferralCode(),
143	        },
144	      });
145	    } catch {
146	      // Almost certainly a race on the unique email/googleId index — re-resolve.
147	      user =
148	        (await db.user.findUnique({ where: { googleId: profile.sub } })) ??
149	        (await db.user.findUnique({ where: { email } }));

150	      if (!user) return fail("google_error");
151	    }
152	    await db.auditLog
153	      .create({ data: { userId: user.id, action: "user.google_register", detail: "Signed up with Google" } })
154	      .catch(() => {});
155	    // Parity with password signup: idempotent welcome credit + welcome email.
156	    // Google verified the email already, so no verification link is sent. The
157	    // credit claim only pays a row whose signupCreditCents is still 0, so a rare
158	    // concurrent-signup race can never pay twice.
159	    try {
160	      const cents = await getSettingInt("signup_free_credit_cents", signupFreeCreditCents());
161	      if (cents > 0) {
162	        const claimed = await db.user.updateMany({
163	          where: { id: user.id, signupCreditCents: 0 },
164	          data: { balanceCents: { increment: cents }, signupCreditCents: cents },
165	        });
166	        if (claimed.count > 0) {
167	          await db.walletTransaction.create({ data: { userId: user.id, amountCents: cents, description: "Welcome credit" } });
168	        }
169	      }
170	    } catch (e) {
171	      console.error("[google] signup credit grant failed for", user.id, e);
172	    }
173	    try {
174	      const { sendMail, emails } = await import("@/lib/mailer");
175	      const tpl = emails.welcome(user.name || "");
176	      await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html, userId: user.id, kind: "welcome" });
177	    } catch {
178	      /* welcome email is best-effort, exactly like password signup */
179	    }
180	  }
181	
182	  if (user.suspended) return fail("account_suspended");
183	
184	  await db.auditLog.create({ data: { userId: user.id, action: "user.login", detail: "Google" } }).catch(() => {});
185	
186	  // Issue the exact same session a password login issues.
187	  await createSession(user.id);
188	
189	  return finish(
190	    NextResponse.redirect(`${base()}${next ?? (user.role === "ADMIN" ? "/admin" : "/dashboard")}`),
191	  );
192	}
