  // visitor never types this code, it only ever arrives via the nxeon_ref
  // cookie set by a real /partner/<code> click (or a bare ?ref=<code> landing
  // on /register), and it is attached ONCE, at account creation — an existing
  // account signing back in via Discord must never pick up or change one
  // (attachCustomerToPartnerByCode's own existing-attachment check, backed by
  // PartnerCustomer.customerId being UNIQUE, is what actually enforces that).
  if (result.isNewAccount) {
    const refCode = req.cookies.get(REF_COOKIE)?.value?.trim().toUpperCase();
    if (refCode) {
      try {
        await attachCustomerToPartnerByCode(result.userId, refCode);
      } catch (e) {
        console.error("[discord] partner attach failed for", result.userId, e);
      }
    }
    // Consumed above — clear it exactly like register()'s jar.delete(REF_COOKIE).
    res.cookies.set({ name: REF_COOKIE, value: "", path: "/", maxAge: 0 });
  }

  return res;
}

