// CREATOR PARTNER PROGRAM — DB-backed discount resolution.
//
// Pure math lives in lib/partner-discount.ts (unit-tested without a database);
// this file is the thin DB layer that resolves a real customer's real attachment
// state and calls it, plus the atomic first-purchase claim used inside a charge
// transaction. Mirrors the coupon-order.ts (pure) / order.ts (DB) split.

import type { Prisma } from "@prisma/client";
import { db } from "./db";
import { partnerDiscountPercent, type PartnerDiscountTier } from "./partner-discount";

export type ResolvedPartnerDiscount = {
  tier: PartnerDiscountTier;
  percent: number;
  partner: { id: string; name: string; code: string } | null;
};

const NONE: ResolvedPartnerDiscount = { tier: "NONE", percent: 0, partner: null };

async function resolveAttachment(userId: string) {
  return db.partnerCustomer.findUnique({
    where: { customerId: userId },
    select: {
      firstPurchaseDiscountUsedAt: true,
      partner: { select: { id: true, name: true, code: true, status: true } },
    },
  });
}

/**
 * Resolve the discount tier for a NEW (non-renewal) order of a non-domain
 * service. `userId` is optional so every quote-function call site can pass it
 * straight through the same options object it already threads a customer id
 * through (or omit it — e.g. an anonymous wizard preview before login — and get
 * `NONE`, byte-identical to pre-partner-program behavior).
 */
export async function partnerDiscountForNewOrder(
  userId: string | null | undefined,
): Promise<ResolvedPartnerDiscount> {
  if (!userId) return NONE;
  const attachment = await resolveAttachment(userId);
  if (!attachment) return NONE;
  const { tier, percent } = partnerDiscountPercent({
    attached: true,
    partnerActive: attachment.partner.status === "ACTIVE",
    isDomain: false,
    firstPurchaseAvailable: attachment.firstPurchaseDiscountUsedAt == null,
  });
  if (tier === "NONE") return NONE;
  return { tier, percent, partner: attachment.partner };
}

/**
 * Resolve the discount tier for a RENEWAL. Always collapses to RECURRING (10%)
 * or NONE — a renewal is, by construction, never anyone's first purchase (see
 * lib/partner-discount.ts's own doc comment on `firstPurchaseAvailable`).
 */
export async function partnerDiscountForRenewal(
  userId: string | null | undefined,
): Promise<ResolvedPartnerDiscount> {
